WITH "m0" AS ( INSERT INTO "public"."mutation_item" AS "s" ( "id" , "score" , "owner_id" ) VALUES ( $1 , $2 , $3 ) ON CONFLICT ON CONSTRAINT "mutation_item_pkey" DO UPDATE SET "score" = "excluded"."score" , "note" = $4 WHERE ( true AND ( ( true ) ) AND ( "s"."owner_id" = $5 ) ) RETURNING "s" AS "t0" , NULL::tid AS "k0" , CAST(CASE WHEN (CASE WHEN "s"."xmax" = 0 THEN "s"."score" >= $6 ELSE "s"."score" <= $7 END) THEN '1' ELSE 'rusuna: permission check failed' || left( "s"."ctid" ::text, 0) END AS integer) AS "check__constraint" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."score" AS "score" ) AS "%")) FROM "r0" AS "t0" )
